 "content": "def transform(grid):
    """Zero every row/column containing a 0 clue, except preserve 2s."""
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    marked_rows = {r for r in range(rows) if 0 in grid[r]}
    marked_cols = {c for c in range(cols) if any(grid[r][c] == 0 for r in range(rows))}
    out = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if (r in marked_rows or c in marked_cols) and grid[r][c] != 2:
                out[r][c] = 0
    return out
